<?php $titulo='Ranking de consumo'; $modulo='ranking'; ?>
<div class="d-flex justify-content-between align-items-start mb-3"><div><h4 class="mb-1">Maiores consumidores</h4><p class="text-muted mb-0">Volume de resposta registrado pelo Squid. Upload por dispositivo não é medido por esta fonte.</p></div><form class="d-flex gap-2"><select name="periodo" class="form-select"><?php foreach($periodos as $k=>$v):?><option value="<?=h($k)?>" <?=$periodo===$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select><select name="limite" class="form-select"><?php foreach([10,20,50] as $n):?><option <?=$limite===$n?'selected':''?>><?=$n?></option><?php endforeach;?></select><button class="btn btn-primary">Aplicar</button></form></div>
<div class="alert alert-info py-2 small">Download e upload são volumes HTTP observados pelo Squid: bytes de resposta e bytes de requisição. Não representam todo o tráfego de rede nem fluxos que bypassam o proxy. Linhas antigas não têm medida de upload.</div>
<?php if($dados):?><div class="card mb-3"><div class="card-body"><div style="height:260px"><canvas id="graficoRanking"></canvas></div></div></div><?php endif;?>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th>#</th><th>Equipamento</th><th>IP</th><th class="text-end">Requisições</th><th class="text-end">Download</th><th class="text-end">Upload</th><th class="text-end">Bloqueios</th><th>Último acesso</th></tr></thead><tbody><?php foreach($dados as $i=>$r):?><tr><td><?=($i+1)?></td><td><?=h($r['equipamento'])?></td><td class="font-monospace"><?=h($r['ip'])?></td><td class="text-end"><?=number_format((int)$r['requisicoes'])?></td><td class="text-end fw-semibold"><?=formatar_bytes((int)$r['download_bytes'])?></td><td class="text-end fw-semibold"><?= $r['upload_bytes']===null?'sem dados':formatar_bytes((int)$r['upload_bytes']) ?></td><td class="text-end"><?=number_format((int)$r['bloqueios'])?></td><td><?=h($r['ultimo_acesso'])?></td></tr><?php endforeach;?><?php if(!$dados):?><tr><td colspan="8" class="text-center text-muted py-4">Sem tráfego registrado nesse período.</td></tr><?php endif;?></tbody></table></div></div>
<?php if($dados):?><script src="/assets/js/chart.umd.min.js"></script><script>(()=>{const d=<?=json_encode(array_map(fn($r)=>['n'=>$r['equipamento'],'d'=>(int)$r['download_bytes'],'u'=>$r['upload_bytes']===null?null:(int)$r['upload_bytes']],$dados),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const gb=v=>v===null?null:+(v/1073741824).toFixed(3);
new Chart(document.getElementById('graficoRanking'),{type:'bar',data:{labels:d.map(x=>x.n),datasets:[{label:'Download',data:d.map(x=>gb(x.d)),backgroundColor:'#0866d9'},{label:'Upload',data:d.map(x=>gb(x.u)),backgroundColor:'#16a34a'}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true,title:{display:true,text:'GB'}}}}});})();</script><?php endif;?>
